defmodule WeddingPlanner.Accounts.EnrollmentLink do
  @moduledoc """
  A single-use, expiring token in one of three flavours (`docs/03-domain-model.md`,
  AUTH-04 through AUTH-09):

  * `"device"` — issued by a user, registers an additional passkey for *that same user*
    (AUTH-04). Issuing and target user are the same.
  * `"user_invitation"` — issued by a user, creates a *new* user and registers their
    first passkey (AUTH-05). The target user does not exist yet, so `target_user_id`
    stays nil until the link is redeemed.
  * `"recovery"` — generated by an operator release command for an existing user who has
    lost every device (AUTH-09). It has no issuing user.

  `token`, `flavour` and the issuing/target user references are set programmatically by
  the builder changesets below, never cast from external input — a token is generated
  server-side and the users are derived from who is calling, not from a form. `expires_at`
  defaults to AUTH-06's 15 minutes but can be overridden, which is useful for testing
  expiry.

  `expires_at`, `used_at` and `revoked_at` are `:utc_datetime` (NFR-21). AUTH-06's
  15-minute enrollment expiry is unrelated to Wax's own WebAuthn challenge timeout
  (`.claude/dr4-webauthn/findings.md`) — the two must not be conflated.
  """
  use Ecto.Schema

  import Ecto.Changeset

  alias WeddingPlanner.Accounts.User

  @type t :: %__MODULE__{}

  @flavours ~w(device user_invitation recovery)
  @default_ttl_seconds 15 * 60

  schema "enrollment_links" do
    field :token, :string
    field :flavour, :string
    field :expires_at, :utc_datetime
    field :used_at, :utc_datetime
    field :revoked_at, :utc_datetime

    belongs_to :issuing_user, User
    belongs_to :target_user, User

    timestamps(type: :utc_datetime)
  end

  @doc "AUTH-06's default enrollment link lifetime, in seconds."
  def default_ttl_seconds, do: @default_ttl_seconds

  @doc """
  AUTH-04: a device link issued by `user`, registering an additional passkey for that
  same user. Issuing and target user are both `user`, set programmatically.
  """
  def device_link_changeset(%User{} = user, attrs \\ %{}) do
    %__MODULE__{issuing_user_id: user.id, target_user_id: user.id}
    |> build_changeset("device", attrs)
  end

  @doc """
  AUTH-05: a user-invitation link issued by `user`, creating a brand-new user when
  redeemed. `target_user_id` is deliberately nil until the link is used.
  """
  def user_invitation_link_changeset(%User{} = user, attrs \\ %{}) do
    %__MODULE__{issuing_user_id: user.id, target_user_id: nil}
    |> build_changeset("user_invitation", attrs)
  end

  @doc """
  AUTH-09: a recovery link for `user`, generated by an operator release command with no
  issuing user behind it.
  """
  def recovery_link_changeset(%User{} = user, attrs \\ %{}) do
    %__MODULE__{issuing_user_id: nil, target_user_id: user.id}
    |> build_changeset("recovery", attrs)
  end

  @doc "AUTH-05: fills in the newly created target user once a user-invitation link is redeemed."
  def assign_target_user_changeset(%__MODULE__{} = link, %User{} = user) do
    change(link, target_user_id: user.id)
  end

  @doc "Marks a link as used at `now` (single-use, AUTH-06)."
  def use_changeset(%__MODULE__{} = link, %DateTime{} = now) do
    change(link, used_at: now)
  end

  @doc "AUTH-07: revokes an unused link at `now`."
  def revoke_changeset(%__MODULE__{} = link, %DateTime{} = now) do
    change(link, revoked_at: now)
  end

  defp build_changeset(link, flavour, attrs) do
    link
    |> cast(attrs, [:expires_at])
    |> put_change(:flavour, flavour)
    |> put_change(:token, generate_token())
    |> default_expiry()
    |> validate_required([:token, :flavour, :expires_at])
    |> validate_inclusion(:flavour, @flavours)
    |> unique_constraint(:token)
  end

  defp default_expiry(changeset) do
    case get_field(changeset, :expires_at) do
      nil ->
        expires_at =
          DateTime.utc_now()
          |> DateTime.add(@default_ttl_seconds, :second)
          |> DateTime.truncate(:second)

        put_change(changeset, :expires_at, expires_at)

      _ ->
        changeset
    end
  end

  defp generate_token do
    :crypto.strong_rand_bytes(32) |> Base.url_encode64(padding: false)
  end
end
